def iscube(a):
    if a < 0:
        a = -a
    if a == 0:
        return True
    low, high = 0, a
    while low <= high:
        mid = (low + high) // 2
        cube = mid ** 3
        if cube == a:
            return True
        elif cube < a:
            low = mid + 1
        else:
            high = mid - 1
    return False
